public class ReinforcedNativeTest extends NativeProof {
static final class NativeWorld extends World {
  final Map<Long,Chunk> chunks=new HashMap<>();final List<ItemStack> spawned=new ArrayList<>();int notifications,lastFlags;
  NativeWorld(){super(new SaveHandlerMP(),new WorldInfo(new NBTTagCompound()),new WorldProviderSurface(),new Profiler(),false);provider.setWorld(this);chunkProvider=createChunkProvider();for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++){Chunk c=new Chunk(this,x,z);c.markLoaded(true);chunks.put(key(x,z),c);}}
  static long key(int x,int z){return ((long)x<<32)^(z&0xffffffffL);}protected IChunkProvider createChunkProvider(){return new IChunkProvider(){public Chunk getLoadedChunk(int x,int z){return chunks.get(key(x,z));}public Chunk provideChunk(int x,int z){return getLoadedChunk(x,z);}public boolean tick(){return false;}public String makeString(){return "real preloaded chunks";}public boolean isChunkGeneratedAt(int x,int z){return getLoadedChunk(x,z)!=null;}};}protected boolean isChunkLoaded(int x,int z,boolean empty){return chunks.containsKey(key(x,z));}public boolean checkLight(BlockPos p){return true;}
  @Override public void notifyBlockUpdate(BlockPos p,IBlockState old,IBlockState next,int flags){lastFlags=flags;notifications++;super.notifyBlockUpdate(p,old,next,flags);}
  @Override public boolean spawnEntity(Entity e){if(e instanceof EntityItem){spawned.add(((EntityItem)e).getItem().copy());return true;}return super.spawnEntity(e);}
 }
 public static void main(String[] args)throws Exception{Bootstrap.register();FMLCommonHandler.instance().beginLoading(net.minecraftforge.fml.server.FMLServerHandler.instance());ModMetadata md=new ModMetadata();md.modId="hbm";md.name="Reinforced placement probe";md.version="1";DummyModContainer c=new DummyModContainer(md);Loader.instance().setupTestHarness(c);Loader.instance().setActiveModContainer(c);ConcreteConstructionSlice.initialize();for(Block b:ConcreteConstructionSlice.blocks()){ForgeRegistries.BLOCKS.register(b);ForgeRegistries.ITEMS.register(new ItemBlock(b).setRegistryName(b.getRegistryName()));runOwner(b);}System.out.println("PASS "+checks+" native reinforced owner checks");}
 static void runOwner(Block b)throws Exception{
  boolean glass=b==ConcreteConstructionSlice.reinforced_glass;NativeWorld w=new NativeWorld();IBlockState state=b.getStateFromMeta(0);check(b.getMetaFromState(state)==0,"zero state roundtrip");check(Block.getStateById(Block.getStateId(state))==state,"native state IDs");check(state.getMaterial()==Material.ROCK,"actual rock material");check(b.getBlockHardness(state,w,BlockPos.ORIGIN)==(glass?2:15),"actual factory hardness");check(b.getExplosionResistance(null)==(glass?15:180),"actual factory resistance");check(b.getLightOpacity(state)==(glass?0:255),"actual factory opacity");
  BlockPos p=new BlockPos(8,96,8);check(w.setBlockState(p,state,3)&&w.getBlockState(p)==state,"real placement");check(!b.hasTileEntity(state)&&w.getTileEntity(p)==null,"no tile lifecycle");for(int fortune=0;fortune<4;fortune++){NonNullList<ItemStack> drops=NonNullList.create();b.getDrops(drops,w,p,state,fortune);check(drops.size()==(glass?0:1),"ordinary drop policy");if(!glass)check(drops.get(0).getItem()==Item.getItemFromBlock(b)&&drops.get(0).getItemDamage()==0&&drops.get(0).getCount()==1,"brick exact native drop");}
  Method silk=Block.class.getDeclaredMethod("getSilkTouchDrop",IBlockState.class);silk.setAccessible(true);ItemStack stack=(ItemStack)silk.invoke(b,state);check(stack.getItem()==Item.getItemFromBlock(b)&&stack.getCount()==1&&stack.getItemDamage()==0,"native silk stack");check(b.canSilkHarvest(w,p,state,null),"native silk harvesting eligibility");
  TestPlayer player=new TestPlayer(w);for(boolean silkTool:new boolean[]{false,true}){ItemStack tool=new ItemStack(net.minecraft.init.Items.DIAMOND_PICKAXE);if(silkTool)tool.addEnchantment(net.minecraft.init.Enchantments.SILK_TOUCH,1);player.setHeldItem(EnumHand.MAIN_HAND,tool);w.spawned.clear();b.harvestBlock(w,player,p,state,null,tool);check(w.spawned.size()==(glass&&!silkTool?0:1),"actual native player harvest silk dispatch");if(!w.spawned.isEmpty()){ItemStack drop=w.spawned.get(0);check(drop.getItem()==Item.getItemFromBlock(b)&&drop.getCount()==1&&drop.getItemDamage()==0,"actual native harvested EntityItem");}}
  net.minecraft.world.chunk.storage.AnvilChunkLoader loader=new net.minecraft.world.chunk.storage.AnvilChunkLoader(new File("chunk-storage"),new net.minecraft.util.datafix.DataFixer(1343));Method write=loader.getClass().getDeclaredMethod("writeChunkToNBT",Chunk.class,World.class,NBTTagCompound.class),read=loader.getClass().getDeclaredMethod("readChunkFromNBT",World.class,NBTTagCompound.class);write.setAccessible(true);read.setAccessible(true);NBTTagCompound saved=new NBTTagCompound();write.invoke(loader,w.getChunk(0,0),w,saved);ByteArrayOutputStream bytes=new ByteArrayOutputStream();CompressedStreamTools.writeCompressed(saved,bytes);NativeWorld fresh=new NativeWorld();Chunk loaded=(Chunk)read.invoke(loader,fresh,CompressedStreamTools.readCompressed(new ByteArrayInputStream(bytes.toByteArray())));fresh.chunks.put(NativeWorld.key(0,0),loaded);loaded.markLoaded(true);check(fresh.getBlockState(p)==state&&fresh.getTileEntity(p)==null,"real compressed Anvil roundtrip");fresh.spawned.clear();check(fresh.destroyBlock(p,true)&&fresh.isAirBlock(p),"real World destruction");check(fresh.spawned.size()==(glass?0:1),"native EntityItem ordinary drop policy");
 }
 static class TestPlayer extends net.minecraft.entity.player.EntityPlayer {TestPlayer(World w){super(w,new com.mojang.authlib.GameProfile(new UUID(0,1),"ReinforcedProbe"));}public boolean isSpectator(){return false;}public boolean isCreative(){return false;}@Override public void addStat(net.minecraft.stats.StatBase stat,int amount){}@Override public void addExhaustion(float amount){}}
}
